package com.bank.feed.processor;

import com.bank.feed.model.EnrichedTransaction;
import com.bank.feed.model.Transaction;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.concurrent.Flow;
import java.util.concurrent.SubmissionPublisher;
import java.util.logging.Logger;

// A Processor is BOTH a Subscriber (consumes raw Transaction)
// AND a Publisher (republishes EnrichedTransaction).
// We extend SubmissionPublisher to reuse its publisher-side plumbing
// and implement Subscriber for the upstream side.
public class FeeEnrichmentProcessor
        extends SubmissionPublisher<EnrichedTransaction>
        implements Flow.Processor<Transaction, EnrichedTransaction> {

    private static final Logger log = Logger.getLogger(FeeEnrichmentProcessor.class.getName());
    // Fee is 0.1% of the transaction amount — always BigDecimal for money.
    private static final BigDecimal FEE_RATE = new BigDecimal("0.001");

    private Flow.Subscription upstream;

    @Override
    public void onSubscribe(Flow.Subscription subscription) {
        this.upstream = subscription;
        // Start by pulling one item — classic demand-based backpressure.
        subscription.request(1);
    }

    @Override
    public void onNext(Transaction txn) {
        BigDecimal fee = txn.amount().multiply(FEE_RATE).setScale(2, RoundingMode.HALF_UP);
        EnrichedTransaction enriched =
                new EnrichedTransaction(txn.txnId(), txn.accountId(), txn.amount(), fee);
        log.info(() -> "ENRICH " + txn.txnId() + " fee=" + fee);
        submit(enriched);              // push downstream (SubmissionPublisher handles demand)
        upstream.request(1);           // pull the next raw item
    }

    @Override
    public void onError(Throwable t) {
        log.severe("Upstream error in enrichment: " + t.getMessage());
        closeExceptionally(t);         // propagate error downstream
    }

    @Override
    public void onComplete() {
        log.info("Upstream complete — closing enrichment processor");
        close();                       // signals onComplete downstream
    }
}
