package com.bank.feed.subscriber;

import com.bank.feed.model.EnrichedTransaction;
import java.util.concurrent.Flow;
import java.util.logging.Logger;

// The slow consumer. It pulls a small batch, processes it, then pulls more.
// This is where backpressure is enforced from the consumer side.
public class FraudVerifierSubscriber implements Flow.Subscriber<EnrichedTransaction> {

    private static final Logger log = Logger.getLogger(FraudVerifierSubscriber.class.getName());
    private static final int BATCH = 2;   // only ever ask for 2 at a time

    private Flow.Subscription subscription;
    private int processedInBatch = 0;

    @Override
    public void onSubscribe(Flow.Subscription subscription) {
        this.subscription = subscription;
        log.info(() -> "Verifier ready — requesting first batch of " + BATCH);
        subscription.request(BATCH);
    }

    @Override
    public void onNext(EnrichedTransaction txn) {
        // Simulate slow external fraud-scoring call.
        try { Thread.sleep(50); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        log.info(() -> "VERIFY " + txn.txnId() + " acct=" + txn.accountId()
                + " amount=" + txn.amount() + " fee=" + txn.fee());
        processedInBatch++;
        if (processedInBatch == BATCH) {
            processedInBatch = 0;
            log.info(() -> "Batch done — requesting next " + BATCH);
            subscription.request(BATCH);   // pull the next batch only when ready
        }
    }

    @Override
    public void onError(Throwable t) {
        log.severe("Verification stream failed: " + t.getMessage());
    }

    @Override
    public void onComplete() {
        log.info("Verification stream complete — all transactions processed");
    }
}
