package com.bank.feed;

import com.bank.feed.model.Transaction;
import com.bank.feed.processor.FeeEnrichmentProcessor;
import com.bank.feed.subscriber.FraudVerifierSubscriber;
import java.math.BigDecimal;
import java.util.List;
import java.util.concurrent.SubmissionPublisher;
import java.util.concurrent.TimeUnit;
import java.util.logging.Logger;

// Wires: SubmissionPublisher (raw feed) -> FeeEnrichmentProcessor -> FraudVerifierSubscriber
public class FlowDemo {
    private static final Logger log = Logger.getLogger(FlowDemo.class.getName());

    public static void main(String[] args) throws InterruptedException {
        try (SubmissionPublisher<Transaction> rawFeed = new SubmissionPublisher<>()) {
            FeeEnrichmentProcessor enricher = new FeeEnrichmentProcessor();
            FraudVerifierSubscriber verifier = new FraudVerifierSubscriber();

            rawFeed.subscribe(enricher);     // feed -> processor
            enricher.subscribe(verifier);    // processor -> verifier

            List<Transaction> batch = List.of(
                new Transaction("TXN-1", "SAV2001", new BigDecimal("50000")),  // Rajesh
                new Transaction("TXN-2", "CUR3001", new BigDecimal("25000")),  // Priya
                new Transaction("TXN-3", "SAV2001", new BigDecimal("12000")),
                new Transaction("TXN-4", "CUR3001", new BigDecimal("80000")),
                new Transaction("TXN-5", "SAV2001", new BigDecimal("3000"))
            );

            log.info("Submitting 5 transactions to a verifier that only wants 2 at a time");
            batch.forEach(rawFeed::submit);  // submit is backpressure-aware; blocks if buffer full
        }
        // Give async pipeline time to drain before JVM exits.
        TimeUnit.SECONDS.sleep(2);
        log.info("Demo finished");
    }
}
