package com.bank.feed;

import com.bank.feed.model.Transaction;
import com.bank.feed.model.EnrichedTransaction;
import com.bank.feed.processor.FeeEnrichmentProcessor;
import java.math.BigDecimal;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.Flow;
import java.util.concurrent.SubmissionPublisher;
import java.util.concurrent.TimeUnit;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class FlowPipelineTest {

    @Test
    void enrichesEveryTransactionWithFee() throws InterruptedException {
        List<EnrichedTransaction> collected = new CopyOnWriteArrayList<>();
        try (SubmissionPublisher<Transaction> feed = new SubmissionPublisher<>()) {
            FeeEnrichmentProcessor enricher = new FeeEnrichmentProcessor();
            feed.subscribe(enricher);
            // Minimal subscriber that pulls everything and records output.
            enricher.subscribe(new Flow.Subscriber<>() {
                public void onSubscribe(Flow.Subscription s) { s.request(Long.MAX_VALUE); }
                public void onNext(EnrichedTransaction e) { collected.add(e); }
                public void onError(Throwable t) { }
                public void onComplete() { }
            });
            feed.submit(new Transaction("T1", "SAV2001", new BigDecimal("50000")));
            feed.submit(new Transaction("T2", "CUR3001", new BigDecimal("25000")));
        }
        TimeUnit.SECONDS.sleep(1);
        assertEquals(2, collected.size());
        // 0.1% of 50000 = 50.00
        assertEquals(new BigDecimal("50.00"), collected.get(0).fee());
    }
}
